// Fixed-kernel filter family executor: nppiFilterHighPass*/LowPass*/Sharpen*/
// Laplace* (plain and Border variants).
//
// Host-visible surface (safe for plain .cpp translation units): the entry-point
// templates are declared here and defined + explicitly instantiated in
// nppi_filter_fixed_executor.cu.  The public wrappers are generated by
// mpp_scripts/gen_family.py (mpp_scripts/families/nppi_filter_*.json).
//
// Semantics (baseline NVIDIA NPP 13.4 on RTX 5090, probe-verified):
//   * Kernels (NppiMaskSize 3_X_3 / 5_X_5 selects the size; Sharpen is 3x3 and
//     takes no mask):
//       HighPass  3x3: 9*center - sum(3x3)      5x5: 25*center - sum(5x5)
//       LowPass   3x3: sum(3x3)/9               5x5: sum(5x5)/25
//       Sharpen   3x3: (16*center - sum(8 neighbours))/8
//       Laplace   3x3: [[-1,-1,-1],[-1,8,-1],[-1,-1,-1]]
//                5x5: [[-1,-3,-4,-3,-1],[-3,0,6,0,-3],[-4,6,20,6,-4],
//                      [-3,0,6,0,-3],[-1,-3,-4,-3,-1]]
//   * Integer destinations use fixed-point emission with C truncating
//     division: HighPass/Laplace are exact; LowPass emits
//     trunc((sum + n/2) / n) (bias 4 for 3x3, 12 for 5x5); Sharpen emits
//     trunc((16*center - sum8 + 3) / 8).  32f passes through float
//     arithmetic without the rounding bias.
//   * Saturation: 8u -> [0,255], 16u -> [0,65535], 16s -> [-32768,32767].
//   * plain variants read raw pixels around pSrc (no clamping); out-of-buffer
//     reads are caller-visible, exactly like NVIDIA NPP.
//   * Border variants support NPP_BORDER_REPLICATE only (any other value
//     returns NPP_NOT_SUPPORTED_MODE_ERROR).  Reads clamp to the source image
//     bounds: pSrc points at oSrcOffset inside the oSrcSize image, and read
//     coordinates are clamped to [-oSrcOffset, oSrcSize-1-oSrcOffset] in
//     pSrc-relative terms.
//   * AC4 (AlphaPreserve=true) computes channels 0..2 and leaves the alpha
//     channel of pDst untouched; C4 computes all four channels.
//   * Validation order, plain masked (probe-verified): null pointers ->
//     negative ROI (NPP_SIZE_ERROR) -> bad eMaskSize (NPP_MASK_SIZE_ERROR) ->
//     zero-size ROI (NPP_NO_ERROR, no writes) -> dst step checks.  Plain
//     unmasked (Sharpen): null -> negative ROI -> zero-size ROI -> step.
//   * Validation order, Border: null -> negative ROI (NPP_SIZE_ERROR) ->
//     oSrcSize <= 0 (NPP_SIZE_ERROR) -> oSrcOffset negative or >= oSrcSize
//     (NPP_OUT_OFF_RANGE_ERROR) -> unsupported border type
//     (NPP_NOT_SUPPORTED_MODE_ERROR) -> [masked only] bad eMaskSize
//     (NPP_MASK_SIZE_ERROR) -> zero-size ROI (NPP_NO_ERROR, skips the step
//     check) -> dst step checks.
//   * Dst step checks (unsigned comparison, probe-verified: a negative step
//     passes): step < ROI row bytes (NPP_STEP_ERROR) -> step not a multiple of
//     the alignment (NPP_NOT_EVEN_STEP_ERROR; element size for C1/C3, pixel
//     size for C4/AC4).  The source step is never validated.
#ifndef NPPI_FILTER_FIXED_EXECUTOR_H
#define NPPI_FILTER_FIXED_EXECUTOR_H

#include "npp.h"

namespace nppi {
namespace filter {

enum FixedOp {
  kHighPass,
  kLowPass,
  kSharpen,
  kLaplace,
};

// Masked 3x3/5x5 fixed-kernel filter (HighPass/LowPass/Laplace; C1/C3/C4/AC4
// plus the Laplace 8u16s / 8s16s conversions).
template <typename Src, typename Dst, int Channels, bool AlphaPreserve, FixedOp Op>
NppStatus filterFixedMask(const Src *pSrc, int nSrcStep, Dst *pDst, int nDstStep, NppiSize oSizeROI,
                          NppiMaskSize eMaskSize, cudaStream_t stream);

// Unmasked fixed 3x3 filter (Sharpen; C1/C3/C4/AC4).
template <typename Src, typename Dst, int Channels, bool AlphaPreserve, FixedOp Op>
NppStatus filterFixed(const Src *pSrc, int nSrcStep, Dst *pDst, int nDstStep, NppiSize oSizeROI,
                      cudaStream_t stream);

// Border variant of the masked filter (NPP_BORDER_REPLICATE only).
template <typename Src, typename Dst, int Channels, bool AlphaPreserve, FixedOp Op>
NppStatus filterFixedMaskBorder(const Src *pSrc, int nSrcStep, NppiSize oSrcSize, NppiPoint oSrcOffset, Dst *pDst,
                                int nDstStep, NppiSize oSizeROI, NppiMaskSize eMaskSize, NppiBorderType eBorderType,
                                cudaStream_t stream);

// Border variant of the unmasked filter (SharpenBorder; REPLICATE only).
template <typename Src, typename Dst, int Channels, bool AlphaPreserve, FixedOp Op>
NppStatus filterFixedBorder(const Src *pSrc, int nSrcStep, NppiSize oSrcSize, NppiPoint oSrcOffset, Dst *pDst,
                            int nDstStep, NppiSize oSizeROI, NppiBorderType eBorderType, cudaStream_t stream);

}  // namespace filter
}  // namespace nppi

#endif  // NPPI_FILTER_FIXED_EXECUTOR_H
